mapper.select:
select * from ( SELECT tmpa.user_name userName, tmpa.user_id userId, tmpa.rep_id repId, b.user_tel userTel, b.reg_time regTime, c.age, c.user_gender userGender, c.birth_date birthDate, c.rep_no repNo, c.report_date reportDate, c.ecg_end_time ecgEndTime FROM ( SELECT user_name, user_id, max(rep_id) rep_id FROM cust_user_ecg_report WHERE dept_id IN ( SELECT dept_id FROM comm_user_mng_dept WHERE user_id =#{loginUserId} ) AND rep_type = 1 GROUP BY user_id, user_name ) tmpa INNER JOIN cust_userinfo b ON tmpa.user_id = b.user_id INNER JOIN cust_user_ecg_report c ON tmpa.rep_id = c.rep_id AND c.rep_type=1 ) temp where 1=1
and userId = #{tm}
and (userName like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%') or userTel like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%'))
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by reportDate DESC,userId desc
